func DiagramLabel(cx *core.Scope, nodes int, edges int) string {
	return For(cx).DiagramLabel(nodes, edges)
}

// DiagramLabel is the package's DiagramLabel in the language of msgs.
func (msgs Messages) DiagramLabel(nodes int, edges int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.DiagramLabel(nodes, edges))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].DiagramLabel; f != nil {
			return f(nodes, edges)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString("Flow chart with ")
			switch i18n.Cardinal("en", float64(nodes)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(nodes))))
				b.WriteString(" node")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(nodes))))
				b.WriteString(" nodes")
			}
			b.WriteString(" and ")
			switch i18n.Cardinal("en", float64(edges)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(edges))))
				b.WriteString(" edge")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(edges))))
				b.WriteString(" edges")
			}
			b.WriteString(".")
			return b.String()
		case "zh-Hans":
			return "包含 " + i18n.FormatNumber("zh-Hans", float64(nodes)) + " 个节点和 " + i18n.FormatNumber("zh-Hans", float64(edges)) + " 条连线的流程图。"
		}
	}
}

